(4234, 'She’s working for an overseas subsidiary of the company.', 'Cô ấy đang làm việc cho một công ty con ở nước ngoài của công ty.', '', 1754210247901, 1754210247901),
(4235, 'The subsidiary has issued shares that are guaranteed by its parent.', 'Công ty con đã phát hành cổ phiếu được công ty mẹ bảo lãnh.', '', 1754210247901, 1754210247901),
(4236, 'Minnwest is the parent company of five community banks.', 'Minnwest là công ty mẹ của năm ngân hàng cộng đồng.', '', 1754210247901, 1754210247901),
(4237, 'The parent company\'s stock price has dropped almost by half.', 'Giá cổ phiếu của công ty mẹ đã giảm gần một nửa.', '', 1754210247901, 1754210247901),
(4238, 'When I\'ve finished the pullover, I might finish off the rest of the wool by making some gloves.', 'Khi hoàn thành chiếc áo chui đầu, tôi có thể sử dụng nốt phần len còn lại này để làm vài cái găng tay.', '', 1754210247901, 1754210247901);
INSERT INTO `example` (`id`, `original`, `translation`, `note`, `last_update`, `created_date`) VALUES
(4239, '\"Go on, finish off this tart, Paul.\" \"Well, it seems a shame to let it go to waste.\"', '\"Ăn nốt cái cái bánh này đi, Paul.\" \"Chà, có vẻ đáng tiếc nếu để nó lãng phí.\"', '', 1754210247901, 1754210247901),
(4240, 'We may as well finish off this wine - there\'s only a little bit left.', 'Uống nốt chỗ rượu này đi - chỉ còn lại một chút thôi.', '', 1754210247901, 1754210247901),
(4241, 'A third heart attack finally finished off the old man.', 'Cơn đau tim thứ ba cuối cùng đã kết liễu ông già.', '', 1754210247901, 1754210247901),
(4242, 'He could spar well enough but he couldn\'t seem to finish off his opponents.', 'Anh ta có thể đấu đủ tốt nhưng dường như anh ta không thể kết liễu đối thủ của mình.', '', 1754210247901, 1754210247901),
(4243, 'Students have to conquer their initial shyness.', 'Học sinh phải vượt qua sự nhút nhát ban đầu của mình.', '', 1754210247901, 1754210247901),
(4244, 'He has finally conquered his fear of spiders.', 'Cuối cùng anh ấy đã chinh phục được nỗi sợ nhện của mình.', '', 1754210247901, 1754210247901),
(4245, 'The Spanish conquered the New World in the 16th century.', 'Người Tây Ban Nha chinh phục Tân Thế giới vào thế kỷ 16.', '', 1754210247901, 1754210247901),
(4246, 'I felt like I had conquered the world.', 'Tôi cảm thấy như mình đã chinh phục được thế giới.', '', 1754210247901, 1754210247901),
(4247, 'We\'re not taking on any new clients at present.', 'Hiện tại chúng tôi không tiếp nhận bất kỳ khách hàng mới nào nữa', '', 1754210247901, 1754210247901),
(4248, 'I can\'t take on any extra work.', 'Tôi không thể đảm nhận thêm bất kỳ công việc nào nữa', '', 1754210247901, 1754210247901),
(4249, 'We were overcharged by £5.', 'Chúng tôi đã bị tính phí cao hơn £ 5', '', 1754210247901, 1754210247901),
(4250, 'Make sure they don\'t overcharge you for the drinks.', 'Hãy chắc chắn rằng họ không tính phí đồ uống quá cao cho bạn.', '', 1754210247901, 1754210247901),
(4251, 'It takes as long as it takes', 'Khi nào xong khác biết', '', 1754210247901, 1754210247901),
(4252, 'Streamline project onboarding', 'tinh gọn quá trình triển khai dự án', '', 1754210247901, 1754210247901),
(4253, 'The production process is to be streamlined.', 'Quy trình sản xuất cần được tinh gọn', '', 1754210247901, 1754210247901),
(4254, 'It would be unethical to carry out such experiments on animals.', 'Sẽ là phi đạo đức nếu thực hiện những thí nghiệm như vậy trên động vật.', '', 1754210247901, 1754210247901),
(4255, 'The doctor was suspended amid accusations of unethical behaviour.', 'Bác sĩ đã bị đình chỉ trong bối cảnh cáo buộc hành vi phi đạo đức.', '', 1754210247901, 1754210247901),
(4256, 'He wouldn\'t sell out the cause to serve his own interests.', 'Anh ta sẽ không bán đứng chính nghĩa để phục vụ lợi ích của mình.', '', 1754210247901, 1754210247901),
(4257, 'French farmers feel they\'ve been sold out by their government in the negotiations.', 'Nông dân Pháp cảm thấy họ đã bị chính phủ bán đứng trong các cuộc đàm phán.', '', 1754210247901, 1754210247901),
(4258, 'My parents freaked when I told them I was pregnant.', 'Bố mẹ tôi hoảng hốt khi tôi nói với họ rằng tôi có thai.', '', 1754210247901, 1754210247901),
(4259, 'A freak midsummer hailstorm caught us all by surprise.', 'Một trận mưa đá kỳ lạ giữa mùa hè khiến tất cả chúng tôi bất ngờ.', '', 1754210247901, 1754210247901),
(4260, 'She was crushed in a freak (= very unlikely) accident in a cave in France.', 'Cô ấy đã bị nghiền nát trong một tai nạn kỳ lạ (= rất khó xảy ra) trong một hang động ở Pháp.', '', 1754210247901, 1754210247901),
(4261, 'Why don\'t you ask the normal question?\" \"Because I\'m freak\"', 'Tại sao bạn không hỏi câu hỏi bình thường?\" \"Bởi vì tôi kỳ quặc\"', '', 1754210247901, 1754210247901),
(4262, 'They should be treated with the dignity proper to all individuals created by God.', 'Họ phải được đối xử với phẩm giá xứng đáng với mọi cá nhân được Thiên Chúa tạo dựng.', '', 1754210247901, 1754210247901),
(4263, 'When are you going to get a proper job?', 'Khi nào bạn mới có được một công việc phù hợp?', '', 1754210247901, 1754210247901),
(4264, 'Nothing is in its proper place.', 'Không có gì ở đúng vị trí của nó', '', 1754210247901, 1754210247901),
(4265, 'The Government is failing to deliver proper care and treatment to people with dementia.', 'Chính phủ không cung cấp dịch vụ chăm sóc và điều trị thích hợp cho những người mắc chứng mất trí nhớ.', '', 1754210247901, 1754210247901),
(4266, 'Please follow the proper procedures for dealing with complaints.', 'Vui lòng thực hiện theo các thủ tục thích hợp để giải quyết khiếu nại.', '', 1754210247901, 1754210247901),
(4267, 'Her lawyer entered a plea of guilty on her behalf.', 'Luật sư của cô đã thay mặt cô nhận tội', '', 1754210247901, 1754210247901),
(4268, 'He refused to listen to her tearful pleas.', 'Anh không chịu nghe lời cầu xin đầy nước mắt của cô', '', 1754210247901, 1754210247901),
(4269, 'a plea to industries to stop pollution', 'lời kêu gọi các ngành công nghiệp ngừng ô nhiễm', '', 1754210247901, 1754210247901),
(4270, 'She made an impassioned plea for help.', 'Cô ấy đã khẩn thiết cầu xin sự giúp đỡ', '', 1754210247901, 1754210247901),
(4271, 'How do you just turn your back on someone?\n', 'Làm thế nào để bạn quay lưng (trở mặt) lại với một ai đó?\n', '', 1754210247901, 1754210247901),
(4272, 'Where do you draw the line between genius and madness?', 'Bạn vẽ ranh giới giữa thiên tài và sự điên rồ ở đâu?', '', 1754210247901, 1754210247901),
(4273, 'Have they done enough to draw a line under the stock market crash?', 'Họ đã làm đủ tốt để vạch ra ranh giới cho sự sụp đổ của thị trường chứng khoán chưa?', '', 1754210247901, 1754210247901),
(4274, 'There comes a time to draw a line under your failures and move on.', 'Sẽ đến lúc bạn phải vạch ra ranh giới cho những thất bại của mình và bước tiếp.', '', 1754210247901, 1754210247901),
(4275, 'I always thought one of my biggest assets was I could see a talented person\n', 'Tôi luôn nghĩ một trong những tài sản lớn nhất của mình là tôi biết nhìn người tài', '', 1754210247901, 1754210247901),
(4276, 'I tried my best to remedy the situation.', 'Tôi đã cố gắng hết sức để khắc phục tình hình', '', 1754210247901, 1754210247901),
(4277, 'He hadn\'t made a very good impression, but that could easily be remedied.', 'Anh ấy đã không tạo được ấn tượng tốt lắm, nhưng điều đó có thể dễ dàng khắc phục được.', '', 1754210247901, 1754210247901),
(4278, 'This could easily be remedied if the authorities were willing.', 'Điều này có thể dễ dàng được khắc phục nếu chính quyền sẵn sàng.', '', 1754210247901, 1754210247901),
(4279, 'This situation is easily remedied.', 'Tình trạng này có thể khắc phục dễ dàng', '', 1754210247902, 1754210247901),
(4280, 'The newborn was perfectly healthy.', 'Trẻ sơ sinh hoàn toàn khỏe mạnh', '', 1754210247902, 1754210247902),
(4281, 'Stay healthy by eating well and exercising regularly.', 'Giữ sức khỏe bằng cách ăn uống tốt và tập thể dục thường xuyên.', '', 1754210247902, 1754210247902),
(4282, 'The researchers then measured brain activity in two groups of healthy subjects.', 'Sau đó, các nhà nghiên cứu đo hoạt động não ở hai nhóm đối tượng khỏe mạnh.', '', 1754210247902, 1754210247902),
(4283, 'The treatment potentially doubles the health benefits for at-risk patients.', 'Việc điều trị có khả năng tăng gấp đôi lợi ích sức khỏe cho những bệnh nhân có nguy cơ cao.', '', 1754210247902, 1754210247902),
(4284, 'Her mental health began to deteriorate.', 'Sức khỏe tinh thần của cô bắt đầu xấu đi', '', 1754210247902, 1754210247902),
(4285, 'Here are some simple ways to improve your health and fitness.', 'Dưới đây là một số cách đơn giản để cải thiện sức khỏe và thể lực của bạn.', '', 1754210247902, 1754210247902),
(4286, 'Her mental health began to deteriorate.', 'Sức khỏe tinh thần của cô bắt đầu xấu đi', '', 1754210247902, 1754210247902),
(4287, 'Your brother’s been hassling me for cash.', 'Anh trai của bạn đã làm phiền tôi vì tiền mặt', '', 1754210247902, 1754210247902),
(4288, 'a strange being from another planet', 'một sinh vật kỳ lạ đến từ hành tinh khác', '', 1754210247902, 1754210247902),
(4289, 'A new era was brought into being by the war.', 'Một thời đại mới được hình thành bởi chiến tranh', '', 1754210247902, 1754210247902),
(4290, 'does it usually happen?', 'nó có thường xảy ra không?\n', '', 1754210247902, 1754210247902),
(4291, 'I suffer from dizzy spells (= short periods when I am dizzy).', 'Tôi bị chóng mặt (= những khoảng thời gian ngắn khi tôi bị chóng mặt).', '', 1754210247902, 1754210247902),
(4292, 'Climbing so high made me feel dizzy.', 'Leo cao quá khiến tôi cảm thấy chóng mặt.', '', 1754210247902, 1754210247902),
(4293, 'The company is backed by overseas investors.', 'Công ty được chống lưng bởi các nhà đầu tư nước ngoài', '', 1754210247902, 1754210247902),
(4294, 'This was her first overseas trip as prime minister.', 'Đây là chuyến công du nước ngoài đầu tiên của bà trên cương vị thủ tướng.', '', 1754210247902, 1754210247902),
(4295, 'The firm is expanding into overseas markets.', 'Công ty đang mở rộng ra thị trường nước ngoài', '', 1754210247902, 1754210247902),
(4296, 'You should always welcome constructive criticism of your work.', 'Bạn nên luôn hoan nghênh những lời chỉ trích mang tính xây dựng về công việc của bạn.', '', 1754210247902, 1754210247902),
(4297, 'She would be falsely modest not to acknowledge that she had come a very long way since those early days.', 'Cô ấy sẽ khiêm tốn một cách giả tạo nếu không thừa nhận rằng cô ấy đã đi được một chặng đường rất dài kể từ những ngày đầu đó.', '', 1754210247902, 1754210247902),
(4298, 'He was a quiet, modest man.', 'Anh là người trầm tính, khiêm tốn', '', 1754210247902, 1754210247902),
(4299, 'Just remember to open your hearts and view things through the lens of one another. That\'ll give you the very thing you need', 'Chỉ cần nhớ mở lòng và nhìn mọi thứ qua lăng kính của nhau. Nó sẽ mang lại cho bạn chính điều bạn cần', '', 1754210247902, 1754210247902),
(4300, 'I know how much soccer means to you\n', 'Tôi biết bóng đá có ý nghĩa với bạn như thế nào\n', '', 1754210247902, 1754210247902),
(4301, 'The system is in imminent danger of collapse.', 'Hệ thống đang có nguy cơ sụp đổ.', '', 1754210247902, 1754210247902),
(4302, 'The heat was becoming unbearable', 'nóng không thể chịu được', '', 1754210247902, 1754210247902),
(4303, 'How far along in the pregnancy are you?', 'Bạn đã mang thai được bao lâu rồi?', '', 1754210247902, 1754210247902),
(4304, 'He was tormented by feelings of insecurity.', 'Anh bị dày vò bởi cảm giác bất an', '', 1754210247902, 1754210247902),
(4305, 'She suffered years of mental torment after her son\'s death.', 'Bà phải chịu đựng nhiều năm dằn vặt về tinh thần sau cái chết của con trai mình.', '', 1754210247902, 1754210247902),
(4306, 'The sea wailed like a soul in torment.', 'Biển gào thét như tâm hồn bị dày vò', '', 1754210247902, 1754210247902),
(4307, 'Rock stars have to get used to being plagued by autograph hunters.', 'Các ngôi sao nhạc rock phải làm quen với việc bị hành hạ bởi việc người hâm mộ xin chữ ký', '', 1754210247902, 1754210247902),
(4308, 'He has been plagued by leg injuries this season.', 'Anh ấy đã bị hành hạn bởi dính chấn thương ở chân trong mùa giải này', '', 1754210247902, 1754210247902),
(4309, 'Economic problems continued to plague the country.', 'Các vấn đề kinh tế tiếp tục hành hạ đất nước', '', 1754210247902, 1754210247902),
(4310, 'The team has been plagued by injury this season.', 'Đội bóng đang bị hành hạ bởi chấn thương trong mùa giải này', '', 1754210247902, 1754210247902),
(4311, 'Financial problems are plaguing the company.', 'Vấn đề tài chính đang hành hạ công ty', '', 1754210247902, 1754210247902),
(4312, 'The interview was sheer torture from start to finish.', 'Cuộc phỏng vấn thực sự là một sự tra tấn từ đầu đến cuối.', '', 1754210247902, 1754210247902),
(4313, 'His confessions were made under torture.', 'Lời thú tội của anh ta được thực hiện dưới sự tra tấn', '', 1754210247902, 1754210247902),
(4314, 'He spent his life tortured by the memories of his childhood.', 'Anh đã sống cuộc đời của mình bởi những ký ức bị tra tấn thời thơ ấu.', '', 1754210247902, 1754210247902),
(4315, 'He was tortured into giving them the information.', 'Anh ta bị tra tấn để cung cấp cho họ thông tin', '', 1754210247902, 1754210247902),
(4316, 'The prisoners were routinely tortured.', 'Các tù nhân thường xuyên bị tra tấn', '', 1754210247902, 1754210247902),
(4317, 'Many of the rebels were captured and tortured by secret police.', 'Nhiều người nổi dậy đã bị cảnh sát mật bắt và tra tấn.', '', 1754210247902, 1754210247902),
(4318, 'Outside there was a sheer drop down to the sea below.', 'Bên ngoài có một đường dốc thẳng đứng rơi xuống biển bên dưới.', '', 1754210247902, 1754210247902),
(4319, 'We were impressed by the sheer size of the cathedral.', 'Chúng tôi rất ấn tượng bởi quy mô cực kì lớn của nhà thờ.', '', 1754210247902, 1754210247902),
(4320, 'The area is under threat from the sheer number of tourists using it.', 'Khu vực này đang bị đe dọa bởi số lượng cực kì lớn khách du lịch sử dụng nó.', '', 1754210247902, 1754210247902),
(4321, 'Do you have that kind of pull? That\'s impressive', 'Bạn có sức hút như vậy không? Cái đấy ấn tượng đấy', '', 1754210247902, 1754210247902),
(4322, 'It is hard to deny the emotional pull of this music.', 'Khó có thể phủ nhận sức lôi cuốn cảm xúc của dòng nhạc này.', '', 1754210247902, 1754210247902),
(4323, 'He felt the pull of paternal love.', 'Anh cảm nhận được sức hút của tình yêu cha', '', 1754210247902, 1754210247902),
(4324, 'The magnetic pull of the city was hard to resist.', 'Sức hút của thành phố thật khó cưỡng lại', '', 1754210247902, 1754210247902),
(4325, 'The tides depend on the pull of the moon.', 'Thủy triều phụ thuộc vào lực hút của mặt trăng', '', 1754210247902, 1754210247902),
(4326, 'He can still pull the girls.', 'Anh ấy vẫn còn có thể thu hút các cô gái', '', 1754210247902, 1754210247902),
(4327, 'They pulled in huge crowds on their latest tour.', 'Họ đã thu hút rất đông khán giả trong chuyến lưu diễn mới nhất của họ', '', 1754210247902, 1754210247902),
(4328, 'The dentist had to pull two of my teeth out', 'Nha sĩ đã phải nhổ hai chiếc răng của tôi ra', '', 1754210247902, 1754210247902),
(4329, 'Pull the curtains—it\'s dark outside.', 'Kéo rèm lại - bên ngoài trời tối rồi', '', 1754210247902, 1754210247902),
(4330, 'The dog snapped at her and she quickly pulled back her hand.', 'Con chó cắn cô và cô nhanh chóng rút tay lại.', '', 1754210247902, 1754210247902),
(4331, 'He tried to kiss her but she pulled away.', 'Anh định hôn cô nhưng cô đẩy ra', '', 1754210247902, 1754210247902),
(4332, 'Ponies were used to pull the coal trucks.', 'Ngựa con được sử dụng để kéo xe chở than', '', 1754210247902, 1754210247902),
(4333, 'The horses pulling the wagon stopped suddenly.', 'Những con ngựa đang kéo xe chợt dừng lại', '', 1754210247902, 1754210247902),
(4334, 'a car pulling a trailer', 'một chiếc ô tô đang kéo rơ-moóc', '', 1754210247902, 1754210247902),
(4335, 'In this area, oxen are used to pull carts.', 'Ở vùng này bò được dùng để kéo xe', '', 1754210247902, 1754210247902),
(4336, 'She pulled on her boots and hurried off.', 'Cô xỏ giày vào và vội vã rời đi', '', 1754210247902, 1754210247902),
(4337, 'He was the only living person pulled from the rubble that night.', 'Anh ấy là người sống duy nhất được kéo ra khỏi đống đổ nát đêm đó.', '', 1754210247902, 1754210247902),
(4338, 'Mary pulled the blanket up over her head.', 'Mary kéo chăn lên qua đầu', '', 1754210247902, 1754210247902),
(4339, 'The sun was too bright so I pulled the blinds down.', 'Nắng quá chói nên tôi kéo rèm xuống.', '', 1754210247902, 1754210247902),
(4340, 'She took his arm and pulled him along.', 'Cô nắm lấy tay anh và kéo anh đi', '', 1754210247902, 1754210247902),
(4341, 'Pull your chair nearer the table.', 'Kéo ghế lại gần bàn', '', 1754210247902, 1754210247902),
(4342, 'They were still pulling bodies from the rubble', 'Họ vẫn đang kéo xác ra khỏi đống đổ nát', '', 1754210247902, 1754210247902),
(4343, 'James pulled his shirt over his head, letting it fall to the floor.', 'James kéo áo qua đầu, để nó rơi xuống sàn.', '', 1754210247902, 1754210247902),
(4344, 'He pulled a knife and stabbed the man.', 'Anh ta rút dao đâm người đàn ông', '', 1754210247902, 1754210247902),
(4345, 'If these weeds are not pulled, they will spread rapidly', 'Nếu những cỏ dại này không được nhổ, chúng sẽ lây lan nhanh chóng.', '', 1754210247902, 1754210247902),
(4346, 'Pull the door shut.', 'Kéo cửa đóng lại', '', 1754210247902, 1754210247902),
(4347, 'She pulled him gently towards her.', 'Cô nhẹ nhàng kéo anh về phía mình', '', 1754210247902, 1754210247902),
