(4977, 'The judge passed the sentence (= said what the punishment would be).', 'Thẩm phán đã thông qua bản án (= cho biết hình phạt sẽ là gì).', '', 1754210247903, 1754210247903),
(4978, 'The court will impose an appropriate sentence.', 'Tòa án sẽ đưa ra mức án thích đáng', '', 1754210247903, 1754210247903),
(4979, 'We don’t all like to admit it, but we all fart', 'Tất cả chúng ta đều không muốn thừa nhận điều đó, nhưng tất cả chúng ta đều đánh rắm', '', 1754210247903, 1754210247903),
(4980, 'I wondered if there might, by any chance, still be any tickets left.', 'Tôi tự hỏi liệu có còn vé nào không', '', 1754210247903, 1754210247903),
(4981, 'Your name isn\'t Walton by any chance, is it?', 'Tên bạn không phải là Walton phải không?', '', 1754210247903, 1754210247903),
(4982, 'Could you get me the latest sales figures, by any chance?', 'Liệu bạn có thể cho tôi số liệu bán hàng mới nhất được không?', '', 1754210247903, 1754210247903),
(4983, 'Could you lend me a couple of pounds, by any chance?', 'Liệu bạn có thể cho tôi mượn vài bảng được không?', '', 1754210247903, 1754210247903),
(4984, 'Are you Hungarian, by any chance?', 'Bạn có phải là người Hungary không?', '', 1754210247903, 1754210247903),
