INSERT INTO `example` (`id`, `original`, `translation`, `note`, `last_update`, `created_date`) VALUES
(5718, 'The report is primarily concerned with aircraft safety.', 'Báo cáo chủ yếu liên quan đến an toàn máy bay.', '', 1754210247904, 1754210247904),
(5719, 'The problem is not primarily a financial one.', 'chủ yếu không phải là vấn đề về tài chính', '', 1754210247904, 1754210247904),
(5720, 'As a consequence, you\'ll feel more clear and see things with greater perspective.', 'Kết quả là, bạn sẽ cảm thấy rõ ràng hơn và nhìn mọi thứ với góc nhìn rộng hơn.', '', 1754210247904, 1754210247904),
(5721, 'We\'ve spoken before about the settled nature of this Galway team under Donoghue and by way of consequence, the consistency of selection.', 'Trước đây chúng ta đã nói về tính chất ổn định của đội Galway dưới sự dẫn dắt của Donoghue và do đó, tính nhất quán của việc lựa chọn.', '', 1754210247904, 1754210247904),
(5722, 'However, participating in protest has resulted in consequences for the star.', 'Tuy nhiên, việc tham gia biểu tình đã gây ra hệ lụy cho ngôi sao.', '', 1754210247904, 1754210247904),
(5723, 'Teenagers are highly influenced by peer pressure.', 'Thanh thiếu niên bị ảnh hưởng nặng nề bởi áp lực bằng bạn bằng bè', '', 1754210247904, 1754210247904),
(5724, 'Parents should be aware if young people develop an unhealthy interest in death and begin to appear depressed.', 'Cha mẹ nên lưu ý nếu trẻ có mối quan tâm không lành mạnh đến cái chết và bắt đầu tỏ ra trầm cảm.', '', 1754210247904, 1754210247904),
(5725, 'Rather than unhealthy competition or discouragement, you use their achievement as motivation to grow yourself, at your own speed', 'Thay vì cạnh tranh không lành mạnh hay chán nản, bạn lấy thành tích của họ làm động lực để phát triển bản thân, theo tốc độ của riêng bạn.', '', 1754210247904, 1754210247904),
(5726, 'She\'s a very accomplished pianist/painter/horsewoman.', 'Cô ấy là một nghệ sĩ piano/họa sĩ/nữ kỵ sĩ rất thành đạt.', '', 1754210247904, 1754210247904),
(5727, 'Constant rejections made him feel worthless.', 'Bị từ chối liên tục khiến anh cảm thấy mình vô dụng', '', 1754210247904, 1754210247904),
(5728, 'Critics say his paintings are worthless.', 'Các nhà phê bình nói rằng những bức tranh của ông là vô giá trị', '', 1754210247904, 1754210247904),
(5729, 'His life was plagued by fear and self-doubt.', 'Cuộc sống của anh bị hành hạ bởi sự sợ hãi và nghi ngờ bản thân', '', 1754210247904, 1754210247904),
(5730, 'The talks will be held without preconditions.', 'Cuộc đàm phán sẽ được tổ chức mà không có điều kiện tiên quyết', '', 1754210247904, 1754210247904),
(5731, 'The reduction of inflation is the precondition of renewed growth.', 'Giảm lạm phát là điều kiện tiên quyết cho tăng trưởng mới.', '', 1754210247904, 1754210247904),
(5732, 'A ceasefire is an essential precondition for negotiation.', 'Lệnh ngừng bắn là điều kiện tiên quyết cần thiết cho đàm phán.', '', 1754210247904, 1754210247904),
(5733, 'Errors can be coding errors made by the programmer, errors due to wrong input, and other unforeseeable things.', 'Lỗi có thể là do lỗi mã lệnh do người lập trình thực hiện, lỗi do nhập liệu sai và những lỗi không thể lường trước khác.', '', 1754210247904, 1754210247904),
(5734, 'Building a dam here could have unforeseeable consequences for the environment.', 'Việc xây dựng một con đập ở đây có thể gây ra những hậu quả khó lường cho môi trường.', '', 1754210247904, 1754210247904),
(5735, 'She has a few thousand dollars put away for her retirement.', 'Cô ấy có vài nghìn đô la để dành cho việc nghỉ hưu của mình.', '', 1754210247904, 1754210247904),
(5736, 'I\'m just going to put the car away (= in the garage).', 'Tôi sẽ cất xe đi (= trong gara).', '', 1754210247904, 1754210247904),
(5737, 'Many refugees were forcibly deported back to the countries they had come from.', 'Nhiều người tị nạn bị buộc phải trục xuất trở lại đất nước mà họ đã xuất phát.', '', 1754210247904, 1754210247904),
(5738, 'He was convicted of drug offenses and deported.', 'Anh ta bị kết án về tội phạm ma túy và bị trục xuất', '', 1754210247904, 1754210247904),
(5739, 'There is no effective serum to desensitize people who are allergic to fleas.', 'Không có huyết thanh hiệu quả để làm mẫn cảm những người bị dị ứng với bọ chét.', '', 1754210247904, 1754210247904),
(5740, 'Doctors and medical researchers have to become desensitized in order to do their jobs.', 'Các bác sĩ và nhà nghiên cứu y tế phải trở nên chai sạn để thực hiện công việc của họ.', '', 1754210247904, 1754210247904),
(5741, 'People are increasingly becoming desensitized to violence on television.', 'Mọi người ngày càng trở nên chai sạn với bạo lực trên truyền hình.', '', 1754210247904, 1754210247904),
(5742, 'the environmental mantra of ‘reduce, reuse, recycle’', 'câu thần chú về môi trường \'giảm thiểu, tái sử dụng, tái chế\'', '', 1754210247904, 1754210247904),
(5743, 'I could always recognize her by the briskness of her gait.', 'Tôi luôn có thể nhận ra cô ấy nhờ dáng đi nhanh nhẹn của cô ấy.', '', 1754210247904, 1754210247904),
(5744, 'Her gait was slow and stately.', 'Dáng đi của cô ấy chậm rãi và trang nghiêm', '', 1754210247904, 1754210247904),
(5745, 'He walked with a rolling gait.', 'Anh bước đi với dáng đi lăn lộn', '', 1754210247904, 1754210247904),
(5746, 'He pushes himself out of his chair and walks over to me. His gait is crooked like his smile.', 'Anh ấy đẩy mình ra khỏi ghế và bước về phía tôi. Dáng đi của anh ấy cũng cong queo như nụ cười của anh ấy.', '', 1754210247904, 1754210247904),
(5747, 'He towered over to me, but he kept his distance so I wouldn\'t have to crane my neck to look him in the eye', 'Anh ấy cao hơn tôi, nhưng anh ấy giữ khoảng cách nên tôi không phải ngước cổ lên nhìn vào mắt anh ấy.', '', 1754210247904, 1754210247904),
(5748, 'People were craning out of the windows and waving.', 'Mọi người đang vươn ra ngoài cửa sổ và vẫy tay', '', 1754210247904, 1754210247904),
(5749, 'She craned her neck to get a better view of the stage.', 'Cô nghểnh cổ lên để nhìn rõ hơn sân khấu.', '', 1754210247904, 1754210247904),
(5750, 'Sam longed for the oblivion of sleep.', 'Sam khao khát được quên đi giấc ngủ', '', 1754210247904, 1754210247904),
(5751, 'He often drinks himself into oblivion.', 'Anh thường uống say đến quên lãng', '', 1754210247904, 1754210247904),
(5752, 'Most of his inventions have been consigned to oblivion.', 'Hầu hết các phát minh của ông đều bị chôn vào quên lãng', '', 1754210247904, 1754210247904),
(5753, 'a minor masterpiece, saved from oblivion', 'một kiệt tác nhỏ đã cứu khỏi bị quên lãng', '', 1754210247904, 1754210247904),
(5754, 'An unexpected victory saved him from political oblivion.', 'Một chiến thắng bất ngờ đã cứu ông khỏi sự lãng quên chính trị.', '', 1754210247904, 1754210247904),
(5755, 'Don\'t scoff—she\'s absolutely right.', 'Đừng chế giễu—cô ấy hoàn toàn đúng', '', 1754210247904, 1754210247904),
(5756, 'He scoffed at our amateurish attempts', 'Anh ấy chế giễu những nỗ lực nghiệp dư của chúng tôi', '', 1754210247904, 1754210247904),
(5757, 'Honestly, he kind of turned me on. I didn\'t even know that guys could turn me on', 'Thành thật mà nói, anh ấy kiểu như làm tôi nổi hứng. Tôi thậm chí còn không biết rằng bọn con trai còn biết khiêu gợi', '', 1754210247904, 1754210247904),
(5758, 'He turned her on to jazz.', 'Anh làm cô ấy thích nhạc jazz', '', 1754210247904, 1754210247904),
(5759, 'She\'s an incurable optimist.', 'Cô ấy là một người lạc quan không thể thay đổi', '', 1754210247904, 1754210247904),
(5760, 'A molecule of water consists of two atoms of hydrogen and one atom of oxygen.', 'Một phân tử nước bao gồm hai nguyên tử hydro và một nguyên tử oxy.', '', 1754210247904, 1754210247904),
(5761, 'There is some discrepancy between the two accounts.', 'Có một số khác nhau giữa hai tài khoản.', '', 1754210247904, 1754210247904),
(5762, 'I thought my number was up. I had an actual near-death experience', 'Tao tưởng tao tới số rồi cơ. Tao suýt chết', '', 1754210247904, 1754210247904),
(5763, 'He was held hostage for almost a year.', 'Anh ta bị bắt làm con tin gần một năm', '', 1754210247904, 1754210247904),
(5764, 'Three children were taken hostage during the bank robbery.', 'Ba đứa trẻ bị bắt làm con tin trong vụ cướp ngân hàng.', '', 1754210247904, 1754210247904),
(5765, 'She promptly seized the opportunity his absence gave her.', 'Cô nhanh chóng nắm bắt cơ hội mà sự vắng mặt của anh mang lại cho cô.', '', 1754210247904, 1754210247904),
(5766, 'The party seized the initiative with both hands (= quickly and with enthusiasm).', 'Đảng đã giành thế chủ động bằng cả hai tay (= nhanh chóng và nhiệt tình).', '', 1754210247904, 1754210247904),
(5767, 'She tried to seize the gun from him.', 'Cô cố giật lấy khẩu súng từ anh', '', 1754210247904, 1754210247904),
(5768, 'He seized her by the arm.', 'Anh nắm lấy tay cô', '', 1754210247904, 1754210247904),
(5769, 'It\'s useless worrying about it.', 'Thật vô ích khi lo lắng về điều đó', '', 1754210247904, 1754210247904),
(5770, 'He knew it was useless to protest.', 'Anh biết có phản đối cũng vô ích', '', 1754210247904, 1754210247904),
(5771, 'you are useless', 'mày đúng là người vô dụng', '', 1754210247904, 1754210247904),
(5772, 'He\'s itching to get back to work.', 'Anh ấy nóng lòng muốn quay trở lại làm việc', '', 1754210247904, 1754210247904),
(5773, 'The crowd was itching for a fight.', 'Đám đông nóng lòng muốn đánh nhau', '', 1754210247904, 1754210247904),
(5774, 'This sweater really itches.', 'Chiếc áo len này thực sự ngứa', '', 1754210247904, 1754210247904),
(5775, 'Does the rash itch?', 'Vết phát ban có ngứa không?', '', 1754210247904, 1754210247904),
(5776, 'I itch all over.', 'Tôi ngứa khắp người', '', 1754210247904, 1754210247904),
(5777, 'There were wide discrepancies in the evidence.', 'Có sự khác biệt lớn trong bằng chứng (bằng chứng không thuyết phục)', '', 1754210247904, 1754210247904),
(5778, 'How do you explain the apparent discrepancies between the money and the receipts?', 'Bạn giải thích thế nào về sự khác biệt rõ ràng giữa số tiền và biên lai?', '', 1754210247904, 1754210247904),
(5779, 'What are the reasons for the discrepancy between girls\' and boys\' performance in school?', 'Nguyên nhân dẫn đến sự khác biệt giữa kết quả học tập của nam và nữ ở trường là gì?', '', 1754210247904, 1754210247904),
(5780, 'The hijackers kept the pilot as a hostage on board the plane.', 'Những kẻ không tặc đã giữ phi công làm con tin trên máy bay.', '', 1754210247904, 1754210247904),
(5781, 'There are various means of transport here in Vietnam but motobikes have always taken the lead', 'Có nhiều loại phương tiện giao thông ở Việt Nam nhưng xe máy là nhiều nhất', '', 1754210247904, 1754210247904),
(5782, 'Findings suggest that while television is more informative than the press, it is less persuasive.', 'Các phát hiện cho thấy rằng dù truyền hình có nhiều thông tin bổ ích hơn báo chí nhưng nó lại kém thuyết phục hơn.', '', 1754210247904, 1754210247904),
(5783, 'The talk was both informative and entertaining.', 'Buổi nói chuyện vừa bổ ích vừa thú vị', '', 1754210247904, 1754210247904),
(5784, 'The only drawback is that it can be somewhat unreliable.', 'Hạn chế duy nhất là nó có thể hơi không đáng tin cậy.', '', 1754210247904, 1754210247904),
(5785, 'We have to find ways of overcoming these drawbacks.', 'Chúng ta phải tìm cách khắc phục những nhược điểm này.', '', 1754210247904, 1754210247904),
(5786, 'This is the one major drawback of the new system.', 'Đây là nhược điểm lớn nhất của hệ thống mới', '', 1754210247904, 1754210247904),
(5787, 'The main drawback to it is the cost.', 'Hạn chế chính của nó là chi phí', '', 1754210247904, 1754210247904),
(5788, 'I’ve only reached level two of the game, so I’m basically still a noob.', 'Tôi mới chỉ đạt đến cấp độ hai của trò chơi nên về cơ bản tôi vẫn còn gà mờ', '', 1754210247904, 1754210247904),
(5789, 'Sorry if this is a noob question.', 'Xin lỗi nếu đây là một câu hỏi gà mờ (câu hỏi khờ khạo)', '', 1754210247904, 1754210247904),
(5790, 'I\'m not a noob, but my trigger fingers just aren\'t what they used to be.', 'Tôi không phải là một kẻ mới vào nghề, nhưng ngón tay cò súng của tôi không còn như trước nữa.', '', 1754210247904, 1754210247904),
(5791, 'The population increase is expected to plateau in the year 2007.', 'Gia tăng dân số dự kiến ổn định trong năm 2007', '', 1754210247904, 1754210247904),
(5792, 'Diversify the problems you solve. If you\'re constantly tackling the same issues, your progress will plateau.', 'Đa dạng hóa các vấn đề bạn giải quyết. Nếu bạn liên tục giải quyết những vấn đề giống nhau, sự tiến bộ trong công việc của bạn sẽ cứ bình bình.', '', 1754210247904, 1754210247904),
(5793, 'People are advised to diversify their investments in the stock market to reduce risk.', 'Mọi người được khuyên nên đa dạng hóa khoản đầu tư của mình vào thị trường chứng khoán để giảm thiểu rủi ro.', '', 1754210247904, 1754210247904),
(5794, 'So, ignore pointless debates online. Choose the framework you\'re most comfortable with or need to learn.', 'Vì vậy, hãy bỏ qua những cuộc tranh luận vô nghĩa trên mạng. Chọn một nền tảng mà bạn cảm thấy thoải mái nhất hoặc cần học.', '', 1754210247904, 1754210247904),
(5795, 'He was thrilled at the prospect of seeing them again.', 'Anh rất phấn khởi trước viễn cảnh được gặp lại họ.', '', 1754210247904, 1754210247904),
(5796, 'I\'m really thrilled with the results.', 'Tôi thực sự phấn khởi với kết quả', '', 1754210247904, 1754210247904),
(5797, 'I was thrilled to be invited.', 'Tôi rất phấn khởi vì được mời', '', 1754210247904, 1754210247904),
(5798, 'She was thrilled to bits (= extremely pleased) that he\'d been offered the job.', 'Cô ấy rất phấn khởi (= cực kỳ hài lòng) rằng anh ấy đã được mời làm việc.', '', 1754210247904, 1754210247904),
(5799, '‘Are you pleased?’ ‘I\'m thrilled.’', '‘Bạn có hài lòng không?’ \'Tôi rất phấn khởi\'', '', 1754210247904, 1754210247904),
(5800, 'Our condolences go to his wife and family.', 'Chúng tôi gửi lời chia buồn tới vợ và gia đình anh ấy', '', 1754210247904, 1754210247904),
(5801, 'If you\'re in a classy restaurant, and you\'re holding the biggest fart of your life, you\'re going to want to keep that fart in even if it kills you, because you don\'t want to be known as the guy who farts at fancy restaurants.', 'Nếu bạn đang ở trong một nhà hàng sang trọng và đang phải nhịn đánh quả rắm lớn nhất trong đời, bạn sẽ phải nhịn đánh rắm ngay cả khi nó giết chết bạn, bởi vì bạn không muốn bị biết mình vừa đánh rắm ở một nhà hàng xịn xò', '', 1754210247904, 1754210247904),
(5802, 'Did you (just) fart?', 'Mày (vừa) xì hơi à?', '', 1754210247904, 1754210247904),
(5803, 'She thinks that any inconvenience is a price worth paying for living in such a beautiful place.', 'Cô cho rằng bất kỳ sự bất tiện nào cũng là cái giá phải trả khi được sống ở một nơi tuyệt đẹp như vậy.', '', 1754210247904, 1754210247904),
(5804, 'He looked terrible this morning. I think he\'s paying the penalty for all those late nights.', 'Sáng nay trông anh thật khủng khiếp. Tôi nghĩ anh ấy đang phải trả giá cho những đêm đi muộn đó.', '', 1754210247904, 1754210247904),
(5805, 'They\'re now paying the price for past mistakes.', 'Họ đang phải trả giá cho những sai lầm trong quá khứ', '', 1754210247904, 1754210247904),
(5806, 'The employees were the ones who had to pay the price.', 'Người lao động chính là người phải trả giá', '', 1754210247904, 1754210247904),
(5807, 'For me, art is like a very fancy thing for rich people.', 'Đối với tôi, nghệ thuật giống như một thứ rất xa hoa đối với người giàu.', '', 1754210247904, 1754210247904),
(5808, 'We stayed in a fancy hotel near the Champs-Élysées.', 'Chúng tôi ở trong một khách sạn xịn xò gần đại lộ Champs-Élysées.', '', 1754210247904, 1754210247904),
(5809, 'fancy restaurants with fancy prices', 'nhà hàng xịn xò với mức giá đắt tiền', '', 1754210247904, 1754210247904),
(5810, 'The marriage had reached rock bottom.', 'Cuộc hôn nhân đã chạm tới đáy vực thẳm', '', 1754210247904, 1754210247904),
(5811, 'Prices hit rock bottom.', 'Giá chạm đáy', '', 1754210247904, 1754210247904),
(5812, 'Unless you’ve been living under a rock for the last few decades, you’ll be aware that Arctic sea ice is melting.', 'Trừ khi bạn là người cổ hủ, trong vài thập kỷ qua, bạn sẽ biết rằng băng ở biển Bắc Cực đang tan chảy.', '', 1754210247904, 1754210247904),
(5813, 'I\'ll have a whisky on the rocks, please.', 'Làm ơn cho tôi một ly whiskey pha đá', '', 1754210247904, 1754210247904),
(5814, 'I think their marriage is on the rocks.', 'Tôi nghĩ cuộc hôn nhân của họ có thể sẽ tan vỡ', '', 1754210247904, 1754210247904),
(5815, 'The name of the shop - \"Strata Various\" - is a play on words, because it sounds like Stradivarius, the famous violin maker.', 'Tên của cửa hàng - \"Strata Different\" - là một cách chơi chữ vì nó nghe giống Stradivarius, nhà sản xuất đàn violin nổi tiếng.', '', 1754210247904, 1754210247904),
(5816, 'He won something of a hollow victory when his opponent was forced to withdraw with a serious injury.', 'Anh ta đã giành được một chiến thắng trống rỗng khi đối thủ buộc phải rút lui vì chấn thương nặng.', '', 1754210247904, 1754210247904),
(5817, 'I\'ve had enough of their hollow promises.', 'Tôi đã chán ngấy những lời hứa sáo rỗng của họ', '', 1754210247904, 1754210247904),
(5818, 'Her stomach felt hollow with fear.', 'Bụng cô trống rỗng vì sợ hãi', '', 1754210247904, 1754210247904),
(5819, 'The tree trunk was hollow inside.', 'Thân cây rỗng bên trong', '', 1754210247904, 1754210247904),
(5820, 'Between 1934 and 1938, Stalin mounted a massive purge of the Communist Party, the government and the armed forces in the Soviet Union.', 'Từ năm 1934 đến năm 1938, Stalin tiến hành một cuộc thanh trừng lớn trong Đảng Cộng sản, chính phủ và lực lượng vũ trang ở Liên Xô.', '', 1754210247904, 1754210247904),
(5821, 'We need to purge our sport of racism.', 'Chúng ta cần thanh lọc môn thể thao phân biệt chủng tộc của mình', '', 1754210247904, 1754210247904),
