(6819, 'It tears me apart to think I might have hurt her feelings.', 'Nó làm tôi giằng xé khi nghĩ rằng tôi có thể đã làm tổn thương cảm xúc của cô ấy.', '', 1754210247912, 1754210247912),
(6820, 'I\'m sorry to disturb you, but can I talk to you for a moment?', 'Tôi xin lỗi vì đã làm phiền bạn, nhưng tôi có thể nói chuyện với bạn một lúc không?', '', 1754210247912, 1754210247912),
(6821, 'Don\'t disturb the papers on my desk.', 'Đừng làm phiền các giấy tờ trên bàn của tôi', '', 1754210247912, 1754210247912),
(6822, 'It disturbed her to realize that she was missing him already.', 'Nó làm cô rối bời khi nhận ra rằng cô đang nhớ anh.', '', 1754210247912, 1754210247912),
(6823, 'If you get up early, try not to disturb everyone else.', 'Nếu bạn dậy sớm, hãy cố gắng không làm phiền mọi người khác.', '', 1754210247912, 1754210247912),
