INSERT INTO `meaning` (`id`, `definition`, `translation`, `typeId`, `itemId`, `pronunciationId`, `antonyms`, `common`, `enable`, `grammar`, `synonyms`, `note`, `collocations`) VALUES
(2, 'awkward because of being large, heavy, or not effective', 'cồng kềnh', 3, 109, 1332, '', 0, 1, '', '', '', ''),
(4, 'used to say that a statement describes a general feeling or opinion relating to or affecting all the people or things in a group', 'nói chung, nhìn chung', 1, 107, 2648, '', 0, 1, '', '', '', ''),
(7, 'having existed for a long time', 'tồn đọng, lâu đời', 3, 110, 2476, '', 1, 1, '', '', '', ''),
(10, 'to make very small changes to something in order to make it work as well as possible:', 'chỉnh sửa, điều chỉnh, tinh chỉnh, hiệu chỉnh', 2, 99, 10, '', 1, 1, '', 'tweak,adjust', 'sửa những chi tiết nhỏ cái gì đó để có thể thực hiện một cách hiệu quả', ''),
(14, 'in a way that becomes quicker and quicker as something that increases becomes larger', 'một cách nhanh chóng (tăng theo cấp số mũ)', 4, 100, 3049, '', 1, 1, '', '', '', ''),
(15, 'not moving in an easy way; lacking grace or skill when moving; not comfortable', 'vụng về, lúng túng (di chuyển)', 3, 108, 429, '', 1, 1, '', '', '', ''),
(18, 'to show that something is true or exists', 'chỉ ra, cho thấy', 2, 103, 1874, '', 1, 1, '', '', '', ''),
(19, 'handle or control (a tool, mechanism, etc.), typically in a skillful manner.', 'vận dụng, xử lý, tính toán, điều khiển', 2, 111, 779, '', 1, 1, '', '', '', ''),
(20, 'write or create something', 'tạo ra (một cách có trật tự)', 2, 101, 20, '', 0, 1, '', '', '', ''),
(21, 'used for saying that you understand what someone is trying to say, especially when you disagree with it', 'tôi hiểu quan điểm của bạn', 1, 112, 3340, '', 0, 1, '', '', '', ''),
(23, 'to try very hard to do something good or helpful', 'còng lưng, cật lực', 1, 102, 2498, '', 0, 1, '', '', '', ''),
(25, 'to name things separately, one by one', 'liệt kê', 2, 106, 34, '', 1, 1, '', 'list', '', ''),
(27, 'to try to deal with something or someone (a problem or difficult task)', '<p>giải quyết, khắc phục (một vấn đề, một công việc..)</p>', 2, 104, 883, '', 1, 1, '', '', '', ''),
(30, 'to start to happen or exist:', 'phát sinh, nảy sinh', 2, 105, 39, '', 0, 1, '', '', '', 'opportunity/problem/issue arise ...'),
(31, 'two people or things together:', 'cả, tất cả', 7, 98, 1352, '', 0, 1, '', '', '', ''),
(32, 'a person or team with a chance of winning a competition', 'ứng cử viên', 1, 113, 41, '', 0, 1, '', '', '', ''),
(33, 'earlier than was expected', 'xảy ra trước, đến trước', 1, 114, 2463, '', 0, 1, '', '', '', 'ahead of/behind time'),
(34, 'to be useful', 'hữu ích, có ích', 1, 115, 3365, '', 0, 1, '', '', '', ''),
(36, 'restricted or limited to the person, group, or area concerned.', 'độc quyền, chỉ có', 3, 117, 1492, '', 0, 1, '', '', '', ''),
(37, 'to make something possible or easier', 'tạo điều kiện', 2, 118, 47, '', 0, 1, '', '', '', ''),
(38, 'feeling ashamed or shy', 'mất mặt, ngượng ngùng, xấu hổ', 3, 119, 284, '', 1, 1, '', '', '', ''),
(39, 'feeling guilty or embarrassed about something you have done or about the quality of your character:', 'hổ thẹn, xấu hổ', 3, 120, 49, '', 1, 1, 'be ashamed of sth/sb/yourself\nbe ashamed to do sth', '', '', ''),
(40, 'the reason why something, especially something bad, happens', 'nguyên nhân, lý do', 1, 121, 50, '', 0, 1, '', '', '', ''),
(42, 'to make something happen, especially something bad', 'gây ra, khiến cho', 2, 121, 52, '', 1, 1, '', '', '', ''),
(43, 'you see something yourself, you will believe it to exist or be true, despite the fact that it is extremely unusual or unexpected', 'trăm nghe không bằng một thấy', 1, 122, 846, '', 0, 1, '', '', '', ''),
(45, 'a situation in which you balance two opposing situations or qualities:', 'sự đánh đổi', 1, 123, 55, '', 0, 1, 'a trade-off (between sth and sth)', '', '', ''),
(48, 'starting from this time;', 'từ giờ trở đi', 4, 124, 2557, '', 0, 1, '', '', '', ''),
(49, '', '', 1, NULL, 59, '', 0, 1, '', '', '', ''),
(50, 'to accept a disadvantage or bad feature in order to have something good:', 'đánh đổi', 2, NULL, 62, '', 1, 1, 'trade something  <=> off (against/for something)', '', '', ''),
(52, 'to notice or understand the difference between two things, or to make one person or thing seem different from another:', 'phân biệt (sự khác nhau)', 2, 125, 2330, '', 1, 1, '', 'differentiate,discriminate', '', ''),
(53, 'the fact of someone or something not succeeding:', 'sự thất bại', 1, 126, 703, '', 0, 1, '', '', '', ''),
(54, 'including all or almost all, the items, details, facts, information, etc., that may be involved', 'toàn diện, toàn bộ, toàn tập', 3, 127, 66, '', 1, 1, 'a comprehensive list of sth: danh sách đầy đủ of sth', 'full,complete', '', 'a comprehensive study/training/guide: nghiên cứu/đào tạo/hướng dẫn toàn diện\na comprehensive account/dialogue: một câu chuyện/cuộc đối thoại toàn diện\ncomprehensive insurance (= covering all risks)\nan extremely/fairly/very/fully comprehensive'),
(55, 'a group of people or things that are the same in some way; a particular variety or type', 'kiểu, loại, chủng loại', 1, 128, 3366, '', 0, 1, '', '', '', ''),
(56, 'used when you are trying to explain or describe something, but you cannot be exact; in some way or to some degree;', '- kiểu như, đại loại như, có thể\n- hơi, khá', 1, 128, 3367, '', 1, 1, '', '', '', ''),
