(5006, '', '<p>Tôi đã gửi yêu cầu hợp nhất để sửa lỗi trên màn hình danh sách dịch vụ AI và danh sách đặt chỗ. Vui lòng xem xét yêu cầu hợp nhất khi bạn có thời gian.</p>', 1, 4598, 7358, '', 1, 1, '', '', '', ''),
(5007, '<ul><li><p style=\"margin-left:0px;\"><i>[uncountable]</i> the act of doing deliberate damage to equipment, transport, machines, etc., to prevent an enemy from using them, or to protest about something</p></li><li><p style=\"margin-left:0px;\"><i>[uncountable] </i>the act of preventing something from being successful or being achieved, especially deliberately</p></li></ul>', '<p>hành động phá hoại</p>', 1, 4599, 7359, '', 1, 1, '', '', '', 'an act of economic/military/industrial sabotage'),
(5008, '<ul><li>to damage or destroy something deliberately to prevent an enemy from using it or to protest about something</li><li>to prevent something from being successful or being achieved, especially deliberately</li></ul>', '<p>phá hoại (nhằm ngăn k cho đạt được mục đích)</p>', 2, 4599, 7360, '', 1, 1, '', '', '', ''),
(5009, '<p>​to prevent somebody from doing something; to prevent something from happening</p>', '<p>loại, loại trừ</p>', 1, 4600, 7363, '', 1, 1, '', '', '', ''),
(5010, '<p>to state that something is not possible or that sb/sth is not suitable</p>', '<p>loại trừ</p>', 1, 4600, 7364, '', 1, 1, 'rule sb/sth  out\nrule sb/sth out (as something) bị loại trừ vi (sth)', 'exclude', '', ''),
(5011, '', '', 1, 4601, 7365, '', 1, 1, '', 'rule out', '', '');
